// The fixture is an authenticated export generated by the real predecessor. Use the ordinary import UI.
import { chromium } from "playwright";
import { readFile, writeFile, mkdir } from "node:fs/promises";
import { gunzipSync } from "node:zlib";
import { createHash } from "node:crypto";
import assert from "node:assert/strict";
import { windowlessRendererOptions } from "./windowless-launch.mjs";
const exportFile = JSON.parse(
  gunzipSync(
    await readFile("src/games/social-engine/persistence/fixtures/v6-auto-with-tail.json.gz"),
  ),
).envelope;
const base = process.env.SE_BASE || "http://127.0.0.1:8230",
  out = "artifacts/social-engine/upgrade/legacy-display";
await mkdir(out, { recursive: true });
const browser = await chromium.launch({
  headless: true,
  executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH,
  ...windowlessRendererOptions(),
});
const page = await browser.newPage({ viewport: { width: 1366, height: 768 } });
const errors = [];
page.on("pageerror", (e) => errors.push(e.message));
const report = {
  status: "FAIL",
  errors,
  sourceSchema: exportFile.schemaVersion,
  sourceSHA256: exportFile.sha256,
};
try {
  const manifest = await page.request.get(base + "/games/social-engine/build-manifest.json");
  const source = await readFile("public/games/social-engine/build-manifest.json");
  assert.deepEqual(await manifest.body(), source);
  report.manifestSha256 = createHash("sha256").update(source).digest("hex");
  await page.goto(base + "/games/social-engine/index.html");
  await page.locator("#continue").click();
  const file = page.waitForEvent("filechooser");
  await page.locator('[data-import="slot-1"]').click();
  await (
    await file
  ).setFiles({
    name: "Deniz.json",
    mimeType: "application/json",
    buffer: Buffer.from(JSON.stringify(exportFile)),
  });
  await page.locator('[data-load="slot-1"]:enabled').click();
  await page.locator("#hud-name").waitFor();
  assert.equal(await page.locator("#hud-name").innerText(), "Deniz");
  await page.locator('[data-panel="phone"]').click();
  await page.locator('[data-tab="news"]').click();
  await page.getByText("Deniz, DARAMCIK’ta yeni bir güne başladı.", { exact: true }).waitFor();
  assert.doesNotMatch(await page.locator("#panel").innerText(), /k[ıi]y[ıi]yaka/iu);
  assert.deepEqual(errors, []);
  await page.screenshot({ path: out + "/historical-news.png" });
  report.status = "PASS";
} catch (e) {
  report.reason = String(e.stack);
  process.exitCode = 1;
} finally {
  await browser.close();
  await writeFile(out + "/results.json", JSON.stringify(report, null, 2));
  console.log(JSON.stringify(report));
}
